$_SESSION['last_seen']=time();
require_once dirname((new ReflectionFunction('db'))->getFileName()).'/BusinessEmailCampaigns.php';
require_once dirname((new ReflectionFunction('db'))->getFileName()).'/BrevoSettings.php';
$actor=(string)($config['admin_user']??'admin');$service=new BusinessEmailCampaigns(db(),$actor);$error='';$notice='';$settings=[];$ready=$service->ready();$id=max(0,(int)($_GET['id']??$_POST['id']??0));
$tab=(string)($_GET['tab']??'campanas');if(!in_array($tab,['campanas','correos','conexion'],true))$tab='campanas';
