if(!empty($_SESSION['brevo_saved_notice'])){$notice='Conexión guardada en el servidor. Usa «Comprobar conexión con Brevo» para verificar el proveedor. No se enviaron correos.';unset($_SESSION['brevo_saved_notice']);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='check_connection'){require_once dirname((new ReflectionFunction('db'))->getFileName()).'/BrevoHealth.php';if(!throttle('brevo_health',5,300))throw new RuntimeException('Espera unos minutos antes de repetir la comprobación.');BrevoHealth::save($directory,BrevoHealth::check($settings));header('Location: '.(($_POST['return_to']??'')==='system'?'index.php?tab=sistema':'campanas.php?tab=conexion'),true,303);exit;}
  elseif($action==='settings'){BrevoSettings::save($directory,$appKey,$_POST);$settings=BrevoSettings::load($directory,$appKey);$_SESSION['brevo_saved_notice']=true;header('Location: campanas.php?tab=conexion',true,303);exit;}
  else{
   if(!$ready)throw new RuntimeException('Aplica el componente 029 en Base de datos para habilitar las campañas.');
   if($action==='permission'){$service->permission((int)($_POST['channel_id']??0),(string)($_POST['decision']??''),(string)($_POST['evidence']??''),($_POST['confirmed']??'')==='1');$notice='Revisión del correo guardada.';$tab='correos';}
   elseif($action==='create'){$id=$service->create($_POST,is_array($_POST['channels']??null)?$_POST['channels']:[],$settings);header('Location: campanas.php?id='.$id,true,303);exit;}
   elseif($action==='approve'&&($_POST['reviewed']??'')==='1'){$service->approve($id,(string)($_POST['hash']??''),$settings);$notice='Versión aprobada. Todavía no se ha enviado ni compartido con Brevo.';}
   elseif($action==='prepare'&&($_POST['confirm_share']??'')==='1'){$c=$service->prepareStep($id,$settings,new BrevoCampaignClient($settings));$notice=$c['status']==='prepared'?'Borrador preparado en Brevo. No se ha enviado.':'Preparación guardada. Puedes continuar desde este punto.';
    if(($_SERVER['HTTP_ACCEPT']??'')==='application/json'){json_response(['status'=>$c['status'],'cursor'=>(int)$c['sync_cursor'],'total'=>count(json_decode($c['recipients_json'],true))]);}
   }
   elseif($action==='send'&&trim((string)($_POST['confirmation']??''))==='ENVIAR'&&($_POST['send_reviewed']??'')==='1'){$service->send($id,(string)($_POST['hash']??''),$settings,new BrevoCampaignClient($settings));$notice='Brevo aceptó la solicitud de envío. Consulta los resultados para comprobar entregas; aceptación no significa entrega.';}
   elseif($action==='refresh'){$service->refresh($id,new BrevoCampaignClient($settings));$notice='Resultados actualizados desde Brevo.';}
   elseif($action==='cancel'){$service->cancel($id);$notice='Campaña cancelada en el panel. Su borrador en Brevo, si existe, se conserva sin enviarse.';}
   else throw new RuntimeException('Revisa la acción y las confirmaciones del formulario.');
  }
 }catch(Throwable $e){http_response_code(400);$error=$e instanceof PDOException?'No se completó la operación. Revisa Base de datos.':$e->getMessage();if($action==='prepare'&&($_SERVER['HTTP_ACCEPT']??'')==='application/json')json_response(['message'=>$error],400);}
}
// Preserve non-secret fields after validation failure; never echo API credentials.
$settingsForm=$settings;if($_SERVER['REQUEST_METHOD']==='POST'&&($action??'')==='settings'&&$error!==''){foreach(['sender_name','sender_email','reply_to','sender_address'] as $field)$settingsForm[$field]=is_string($_POST[$field]??null)?substr($_POST[$field],0,1000):'';$settingsForm['enabled']=($_POST['enabled']??'')==='1';$tab='conexion';$error.=' Los demás datos siguen en el formulario; por seguridad, vuelve a pegar la clave API si la habías escrito.';}
